-- البرج · Burj leaderboard schema. Run once in the Supabase SQL editor.
-- Then run supabase/seed.private.sql (generated by `npm run build`, gitignored)
-- to load the answers. Answers live only in floor_answers, never in the repo.
--
-- Access model:
--   * All tables have RLS on and no policies: the anon key cannot read or write them.
--   * The public reads two views that expose only nickname, town, floor and time.
--   * All writes go through the submit-score Edge Function, which uses the
--     service-role key that Supabase injects into the function environment.

create table if not exists public.floor_answers (
  floor        int primary key check (floor > 0),
  answers      text[] not null check (cardinality(answers) > 0), -- normalized, see docs/burj/js/normalize.js
  released_at  timestamptz not null default now()               -- floors in the future are not accepted yet
);

create table if not exists public.players (
  device_id      uuid primary key,
  nickname       text not null check (char_length(nickname) between 1 and 20),
  town           text not null check (char_length(town) between 1 and 60),
  highest_floor  int  not null default 0 check (highest_floor >= 0),
  reached_at     timestamptz not null default now(),  -- when highest_floor was reached
  created_at     timestamptz not null default now(),
  last_submit_at timestamptz not null default now()
);
create index if not exists players_rank on public.players (highest_floor desc, reached_at asc);
create index if not exists players_town on public.players (town);

-- One row per submission attempt, for rate limiting.
create table if not exists public.submissions (
  id         bigint generated always as identity primary key,
  device_id  uuid,
  ip_hash    text,
  ok         boolean not null,
  reason     text,
  created_at timestamptz not null default now()
);
create index if not exists submissions_device_time on public.submissions (device_id, created_at desc);
create index if not exists submissions_ip_time on public.submissions (ip_hash, created_at desc);

alter table public.floor_answers enable row level security;
alter table public.players       enable row level security;
alter table public.submissions   enable row level security;
revoke all on public.floor_answers, public.players, public.submissions from anon, authenticated;

-- Public, read-only views. They run with the owner's rights (security_invoker off)
-- on purpose, so they can read players through RLS while exposing only these columns.
create or replace view public.leaderboard_players
with (security_invoker = false) as
  select nickname, town, highest_floor, reached_at
  from public.players
  where highest_floor > 0;

create or replace view public.leaderboard_towns
with (security_invoker = false) as
  select town,
         count(*)::int                              as players,
         round(avg(highest_floor)::numeric, 2)      as avg_floor,
         max(highest_floor)                         as best_floor
  from public.players
  where highest_floor > 0
  group by town;

revoke all on public.leaderboard_players, public.leaderboard_towns from anon, authenticated;
grant select on public.leaderboard_players, public.leaderboard_towns to anon, authenticated;

-- Optional housekeeping (needs the pg_cron extension): keep 7 days of attempts.
-- select cron.schedule('burj-prune-submissions', '17 3 * * *',
--   $$delete from public.submissions where created_at < now() - interval '7 days'$$);
